// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class UnregisteredCheckinWarningTest {

    private static final long SHORT_WARNING_INTERVAL_MS = 50;

    private final SupervisionTestWatchdogServiceImpl svc = new SupervisionTestWatchdogServiceImpl();
    private final TestCC component = new TestCC("unregisteredCheckinComponent", 60000);

    @Test
    public void checkinFromUnregisteredComponentIsReported() {
        whenComponentChecksIn(1);

        thenUnregisteredCheckinWarningsAre(1);
    }

    @Test
    public void repeatedCheckinsFromUnregisteredComponentAreRateLimited() {
        whenComponentChecksIn(5);

        thenUnregisteredCheckinWarningsAre(1);
    }

    @Test
    public void checkinFromUnregisteredComponentIsReportedAgainAfterTheInterval() throws Exception {
        givenUnregisteredCheckinWarningInterval(SHORT_WARNING_INTERVAL_MS);

        whenComponentChecksIn(1);
        whenWarningIntervalElapses();
        whenComponentChecksIn(1);

        thenUnregisteredCheckinWarningsAre(2);
    }

    @Test
    public void checkinFromComponentUnregisteredAfterRegistrationIsReported() {
        givenComponentIsRegistered();
        givenComponentIsUnregistered();

        whenComponentChecksIn(1);

        thenUnregisteredCheckinWarningsAre(1);
    }

    @Test
    public void checkinFromRegisteredComponentIsNotReported() {
        givenComponentIsRegistered();

        whenComponentChecksIn(3);

        thenUnregisteredCheckinWarningsAre(0);
    }

    @Before
    public void activateDisabledWatchdogService() {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", false);
        this.svc.activate(properties);
    }

    @After
    public void cleanup() {
        this.svc.deactivate();
    }

    private void givenUnregisteredCheckinWarningInterval(final long intervalMs) {
        this.svc.setUnregisteredCheckinWarningIntervalNs(TimeUnit.MILLISECONDS.toNanos(intervalMs));
    }

    private void givenComponentIsRegistered() {
        this.svc.registerCriticalComponent(this.component);
    }

    private void givenComponentIsUnregistered() {
        this.svc.unregisterCriticalComponent(this.component);
    }

    private void whenComponentChecksIn(final int times) {
        for (int i = 0; i < times; i++) {
            this.svc.checkin(this.component);
        }
    }

    private void whenWarningIntervalElapses() throws InterruptedException {
        Thread.sleep(SHORT_WARNING_INTERVAL_MS * 2);
    }

    private void thenUnregisteredCheckinWarningsAre(final int expectedWarnings) {
        assertEquals(expectedWarnings, this.svc.getUnregisteredCheckinWarnings());
    }
}
